import{d,C as n,o as g,c as h,a3 as e,E as s,j as a,a as p}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第七章","description":"《正易心法》第七章——天地万物，理有未明，观于卦脉则理昭然：坎兑艮离四画推知月为地气、日为天气、山自天来、雨从地出，卦画如浑仪。","frontmatter":{"title":"正易心法·第七章","description":"《正易心法》第七章——天地万物，理有未明，观于卦脉则理昭然：坎兑艮离四画推知月为地气、日为天气、山自天来、雨从地出，卦画如浑仪。","category":"guide","aliases":["正易心法第七章","观于卦脉","卦脉"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-07.md","filePath":"yijing/zheng-yi-xin-fa/chapter-07.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-07.md"},x=d({...c,setup(u){const o=[{id:"z7-01",label:"一、观于卦脉",showLabel:!0,sentences:[["天地万物，理有未明。观于",{text:"卦脉",glossary:"guamai"},"，理则",{text:"昭然",glossary:"zhaoran"},"。"]],note:["天地万物的道理，有许多尚未明了；但观察卦脉，这些道理便昭然若揭。（这是全书第二个核心概念：第一章讲「落处」，本章讲「卦脉」——落处是义理落在哪里，卦脉是阴阳如何流到那里。）"]},{id:"z7-02",label:"二、卦脉审",showLabel:!0,sentences:[["卦脉，为运动流行自然之理也。卦脉",{text:"审",glossary:"shen"},"，则天地万物之理得矣。"]],note:["所谓卦脉，是阴阳运动流行的自然之理；把卦脉审察清楚，天地万物的道理便可得到。（「脉」字极妙：人体有血脉，气血在其中流行；卦画有卦脉，阴阳在其中运动——两者是同一件事的两个层面，呼应第二章的「血气流行」。）"]},{id:"z7-03",label:"三、四画观法",showLabel:!0,sentences:[["如观坎画，则知月为地之气；观离画，则知日为天之气；观艮画，则知山自天来；观兑画，则知雨从地出。"]],note:["比如：观坎卦之画，便知月亮是地气所生；观离卦之画，便知太阳是天气所成；观艮卦之画，便知山是从天上降来的；观兑卦之画，便知雨是从地下升出的。四个结论都由卦画的爻位结构推出——坎（阳陷阴中）如月，外阴内阳；离（阴附阳中）如日，外阳内阴；艮（一阳在上）如山，天气自上凝结；兑（一阴在上）如雨，地气上升为阴。"]},{id:"z7-04",label:"四、观叠交",showLabel:!0,sentences:[["观",{text:"叠交",glossary:"diejiao"},"，则知",{text:"闰余之数",glossary:"runyu"},"；"]],note:["观卦画的叠交，便知历法闰余之数的道理。（坎为月、离为日，日月交叠运行：阴历一年约 354 天，阳历一年约 365 天，差约 11 天，故三年一闰、五年二闰、十九年七闰——闰余之数正是从「日月叠交」中自然显现的。）"]},{id:"z7-05",label:"五、观交体",showLabel:!0,sentences:[["观",{text:"交体",glossary:"jiaoti"},"，则知",{text:"造化之原",glossary:"zaohua"},"。"]],note:["观卦画的交体，便知造化生成的根源。（交体即上下卦交叠而成的整体，最典型者是坎离相交：坎☵与离☲交叠为既济（水火既济，造化完成之象）或未济（火水未济，造化未完成之象）。）"]},{id:"z7-06",label:"六、浑仪之器",showLabel:!0,sentences:[["凡此卦画，皆所以写天地万物之理于目前，亦若",{text:"浑仪",glossary:"hunyi"},"之器也。"]],note:["凡此种种卦画，都是把天地万物的道理写在眼前，就像浑天仪这件仪器一样。（浑天仪以铜环模拟天球运行，是天地运行的物理模型；卦画模拟阴阳运动，是天地的符号模型——都可以操作、可以观测、可以推演。麻衣以此说明：卦画不是抽象符号，而是天地运行的直接模型。）"]}],r=[{id:"guamai",term:"卦脉",pinyin:"guà mài",meaning:"卦的脉络，即卦画中阴阳流动的运动轨迹。本章核心词，与第一章「落处」并列，构成方法论的两大支柱。"},{id:"zhaoran",term:"昭然",pinyin:"zhāo rán",meaning:"明白显著，清晰可见。"},{id:"shen",term:"审",pinyin:"shěn",meaning:"仔细察看、明辨。审察卦脉，即细观卦画结构。"},{id:"diejiao",term:"叠交",pinyin:"dié jiāo",meaning:"卦画的重叠交错，指上下卦交叠形成的结构关系。"},{id:"runyu",term:"闰余之数",pinyin:"rùn yú zhī shù",meaning:"历法中多余的天数。阴历与阳历的差值，用来置闰。"},{id:"jiaoti",term:"交体",pinyin:"jiāo tǐ",meaning:"交叠的卦体，上下卦交叉形成的整体结构。"},{id:"zaohua",term:"造化之原",pinyin:"zào huà zhī yuán",meaning:"造化的根源，天地生成万物的根本原理。"},{id:"hunyi",term:"浑仪",pinyin:"hún yí",meaning:"浑天仪，古代天文观测仪器，以铜环模拟天球运动。"}];return(b,t)=>{const i=n("DaoTextReading"),l=n("DaoKeywordCards");return g(),h("div",null,[t[0]||(t[0]=e(`<h1 id="正易心法·第七章" tabindex="-1">正易心法·第七章 <a class="header-anchor" href="#正易心法·第七章" aria-label="Permalink to &quot;正易心法·第七章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章引入全书<strong>第二个核心概念：卦脉</strong>。</p><p>与第一章「落处」并列，构成麻衣方法论的两大支柱：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>落处（第一章）= 卦画义理的实际所指</span></span>
<span class="line"><span>          +</span></span>
<span class="line"><span>卦脉（第七章）= 卦画中阴阳流动的运动轨迹</span></span>
<span class="line"><span>          ↓</span></span>
<span class="line"><span>两者合用 = 既知卦义落在哪里，又知阴阳如何流到那里</span></span></code></pre></div><p><strong>「脉」字极妙</strong>：脉的本义是血管中血液流动的通道。<strong>卦脉，就是卦画中阴阳气流动的通道与轨迹。</strong> 这与第二章「血气流行」形成呼应——<strong>人体有血脉，卦画有卦脉，两者是同一件事的两个层面。</strong></p><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>四画观法</strong>——四个结论全部由卦画的爻位结构推出：</p><table tabindex="0"><thead><tr><th>卦</th><th>结构</th><th>观出的理</th></tr></thead><tbody><tr><td>坎 ☵</td><td>阳陷阴中</td><td><strong>月为地之气</strong>（外阴内阳，如月借日光）</td></tr><tr><td>离 ☲</td><td>阴附阳中</td><td><strong>日为天之气</strong>（外阳内阴，如日中有黑子）</td></tr><tr><td>艮 ☶</td><td>一阳在上</td><td><strong>山自天来</strong>（天气自上凝结）</td></tr><tr><td>兑 ☱</td><td>一阴在上</td><td><strong>雨从地出</strong>（地气上升为阴）</td></tr></tbody></table><p><strong>浑仪之喻</strong>：</p><table tabindex="0"><thead><tr><th>浑天仪</th><th>卦画</th></tr></thead><tbody><tr><td>铜环模拟天球运行</td><td>卦画模拟阴阳运动</td></tr><tr><td>可直接观测天象</td><td>可直接读取天地之理</td></tr><tr><td>是天地的物理模型</td><td>是天地的符号模型</td></tr></tbody></table><p><strong>麻衣用「浑仪」作比，是在说：卦画不是抽象符号，而是天地运行的直接模型——就像浑天仪一样，可以操作、可以观测、可以推演。</strong></p><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先读「卦脉」的定义（运动流行的自然之理）；</li><li>再看四卦的观法，<strong>注意它和第一章的说法是一致的</strong>（坎得乾中爻、艮得乾上爻）；</li><li><strong>留意原文一处传抄可疑</strong>（见下注）——遇到文意不通处，须回到卦画验证。</li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>卦脉</strong>：卦画中阴阳流动的轨迹，是「运动流行自然之理」。</li><li><strong>四画观法</strong>：坎（月）、离（日）、艮（山）、兑（雨）。</li><li><strong>叠交</strong>：日月交叠 → 闰余之数。</li><li><strong>交体</strong>：坎离交织 → 既济／未济，造化之原。</li><li><strong>浑仪之喻</strong>：卦画是天地运行的直接模型。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,17)),s(i,{colophon:"观于卦脉 · 四画观法 · 叠交闰余 · 浑仪之器",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第七章原文",sections:o,glossary:r}),t[1]||(t[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入。原文「观离画，则知雨从地出」「观叠交，则知曰为天之气」两处疑有传抄之误——离为日（非雨），「曰」当为「日」；参考第一章「坎得乾中爻，故月自天之中而运」的用法，此处顺序当为坎（月）、离（日）、艮（山）、兑（雨）。此类讹误在古籍中常见，正是训诂学存在的理由之一；遇到文意不通处，不可盲诵，须回卦画结构验证。")],-1)),t[2]||(t[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[p("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),s(l,{items:[{term:"卦脉",pinyin:["guà","mài"],meaning:"卦画中阴阳流动的运动轨迹。与第一章「落处」并列，是麻衣方法论的第二支柱。"},{term:"四画观法",pinyin:["sì","huà"],meaning:"由卦画的爻位结构推知自然现象：坎（阳陷阴中）为月、离（阴附阳中）为日、艮（一阳在上）为山、兑（一阴在上）为雨。"},{term:"叠交 · 闰余",pinyin:["dié","jiāo"],meaning:"日月交叠运行，一年差约十一日，故三年一闰——闰余之数从「坎离叠交」中自然显现。"},{term:"交体",pinyin:["jiāo","tǐ"],meaning:"上下卦交叠而成的整体。坎离相交为既济／未济，是造化完成与未完成的两个象征。"},{term:"浑仪之器",pinyin:["hún","yí"],meaning:"浑天仪以铜环模拟天球；卦画模拟阴阳运动。麻衣以此说明卦画是天地的直接模型，不是抽象符号。"}]}),t[3]||(t[3]=e(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章引入全书第二个核心概念：<strong>卦脉</strong>——卦画中阴阳流动的运动轨迹。</p><p><strong>「脉」字极妙</strong>：人体有血脉，气血在其中流行；卦画有卦脉，阴阳在其中运动——<strong>两者是同一件事的两个层面（天人同构）</strong>。</p><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>四画观法</strong>，全部由卦画的爻位结构推出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>坎☵ 阳陷阴中 → 月（外阴内阳，借日光）</span></span>
<span class="line"><span>离☲ 阴附阳中 → 日（外阳内阴）</span></span>
<span class="line"><span>艮☶ 一阳在上 → 山（天气自上凝结）</span></span>
<span class="line"><span>兑☱ 一阴在上 → 雨（地气上升为阴）</span></span></code></pre></div><p><strong>原文疑有传抄之误</strong>——两处需校勘：</p><table tabindex="0"><thead><tr><th>原文（疑误）</th><th>校勘后</th></tr></thead><tbody><tr><td>观离画，则知<strong>雨从地出</strong></td><td>观离画，则知<strong>日为天之气</strong>（离＝日）</td></tr><tr><td>观<strong>叠交</strong>，则知<strong>曰</strong>为天之气</td><td>观<strong>艮画</strong>，则知<strong>山自天来</strong>（艮＝山）</td></tr></tbody></table><blockquote><p>这正是训诂学存在的理由之一：<strong>遇到文意不通处，不可盲诵，须回到卦画结构验证</strong>——这本身就是「落处」方法的实践。</p></blockquote><p><strong>「月为地之气」的深层含义</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>天 = 阳 = 日 = 离 = 火气</span></span>
<span class="line"><span>地 = 阴 = 月 = 坎 = 水气</span></span></code></pre></div><p>月亮盈亏 ↔ 潮汐涨落（地之水气）；月经周期 ↔ 月相周期；植物生长 ↔ 月相变化。<strong>这不是迷信，而是一套以阴阳为基础的系统观察</strong>——月与地的关联，在现代天文学中也有实证（潮汐、月球引力）。</p><p><strong>与《说卦传》的比较</strong>：</p><table tabindex="0"><thead><tr><th>比较点</th><th>《说卦传》</th><th>麻衣卦脉说</th></tr></thead><tbody><tr><td>解释方式</td><td>列举卦的象征物</td><td>从卦画结构推导自然现象</td></tr><tr><td>逻辑方向</td><td>卦→象（给出对应）</td><td>象→卦（解释为什么）</td></tr><tr><td>月与坎</td><td>坎为月</td><td>坎画一阳陷阴→月为地气（给出原因）</td></tr><tr><td>深度</td><td>给出结论</td><td>结论 + 推导过程</td></tr></tbody></table><blockquote><p>《说卦传》是<strong>索引</strong>，麻衣是<strong>推导</strong>。索引可以背诵，推导必须理解——这正是麻衣批评「盲诵古人语」的落脚点。</p></blockquote><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li><strong>钩子回收</strong>：第一章的「艮得乾上爻，故山自天上而坠」，本章正式展开为「观艮画，则知山自天来」——<strong>这是卦脉的必然推论，不是神话，是象数逻辑。</strong></li><li>四画观法可以自己推一遍：拿一张纸画坎离艮兑，看爻位怎么对应月日山雨；</li><li>记得「浑仪」这个比喻：<strong>读卦像读仪器，不是读文章。</strong></li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>天地万物的道理，有许多尚未明了；但观察卦脉，这些道理便昭然若揭。</p><p>所谓卦脉，是阴阳运动流行的自然之理；把卦脉审察清楚，天地万物的道理便可得到。</p><p>比如：观坎卦之画，便知月亮是地气所生；观离卦之画，便知太阳是天气所成；观艮卦之画，便知山是从天上降来的；观兑卦之画，便知雨是从地下升出的。</p><p>观卦画的叠交，便知历法闰余之数的道理；观卦画的交体，便知造化生成的根源。</p><p>凡此种种卦画，都是把天地万物的道理写在眼前，就像浑天仪这件仪器一样。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第七章给了「象」一个看得见的<strong>机制</strong>——<strong>不是「坎为月」这种对应，而是「坎的这一画为什么就是月」。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「卦脉」与「落处」</strong>——落处是「义理落在哪」，卦脉是「阴阳怎么流到那」。<strong>这两个词合起来，才是完整的读卦法。</strong></li><li><strong>脉字的借用</strong>——人体有血脉，卦画有卦脉。这与第二章「血气流行」是同一套天人同构的推法。<strong>「脉」这个词，是不是让抽象的卦画一下子活起来了？</strong></li><li><strong>浑仪之喻</strong>——<strong>卦画是可以「操作」的仪器，不是拿来「读」的文章。</strong> 这句话我记下了：我平时读卦，是当文章读，还是当仪器用？</li><li><strong>传抄之误的启示</strong>——原文两处疑似讹误。<strong>麻衣自己的方法是「不可盲诵，须回卦画验证」——这句话正好可以用来读麻衣自己的文本。</strong> 这很有趣：一部反对「盲诵」的书，也要求读者不盲诵它。</li><li><strong>钩子回收</strong>：第一章「山自天上而坠」到本章正式收束——<strong>四个视角（卦脉、地质、陨石、共工触山）说的是同一件事：山与天的关联。</strong></li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-01">第一章 · 羲皇易道</a> — 「艮得上爻，故山自天上而坠」（本章展开）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-02">第二章 · 六画之设</a> — 「血气流行」与「卦脉」同理</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-06">第六章 · 消息卦画</a> — 「辞外见意」（本章是据此推出的自然结论）</li><li><a href="/Dao/yijing/shi-yi/shuo-gua-zhuan">说卦传</a> — 「坎为水、离为火、艮为山、兑为泽」是索引，本章是推导</li></ul>`,30))])}}});export{y as __pageData,x as default};
